        ts: Date.now()
      },
      "WARN",
      msg.topic || null
    );

    return [null, null, outLogPartial];
  }

  // 5. Limiar atingido
  if (count >= 3) {
    flow.set("await_count", 0);

    // ativa a regra global
    global.set("regra1", true);

    // -----------------------------
    // SaÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â­da 1: e-mail
