if (cycleDeltaPct > 0.15) anomalyScore += 0.20;
if (tempDeltaPct > 0.10) anomalyScore += 0.15;
if (rpmDeltaPct < -0.10) anomalyScore += 0.15;
if (torqueDeltaPct > 0.10) anomalyScore += 0.10;
